func _run_tests() -> void:
	var script_res: GDScript = load("res://story/story_validator.gd") as GDScript
	if not check("script_caricato", script_res != null, "Lo script res://story/story_validator.gd deve essere valido e caricabile"):
		return

	var validator: Object = script_res.new()
	if not check("istanza", validator != null, "StoryValidator deve poter essere istanziato"):
		return

	if not check("metodo_validate", has_function(validator, "validate_chapter"), "StoryValidator deve implementare la funzione validate_chapter(file_path)"):
		return

	# Verifica che le storie ufficiali del gioco non abbiano errori
	var official_stories: Array[String] = [
		"res://story/intro.json",
		"res://story/branching_story.json",
		"res://story/network_story.json",
		"res://story/consequence_story.json"
	]
	for story_path in official_stories:
		var errs: Variant = validator.call("validate_chapter", story_path)
		var is_arr: bool = errs is Array
		var err_count: int = (errs as Array).size() if is_arr else -1
		if not check("storia_" + story_path.get_file().get_basename(), is_arr and err_count == 0, "La storia %s deve essere valida senza errori (trovati: %d)" % [story_path, err_count]):
			return

	# Verifica che un file inesistente venga segnalato come errore
	var missing_errs: Variant = validator.call("validate_chapter", "res://story/non_esiste_affatto.json")
	check("file_mancante", missing_errs is Array and not (missing_errs as Array).is_empty(), "validate_chapter deve segnalare errore se il file non esiste")

	# Verifica che un file con errori venga rilevato correttamente
	var bad_path := "user://test_story_with_errors.json"
	var f := FileAccess.open(bad_path, FileAccess.WRITE)
	if f:
		var bad_json := '{"lines": [{"speaker": "PersonaggioSconosciuto", "text": "Ciao"}, {"type": "jump", "target": "etichetta_fantasma"}]}'
		f.store_string(bad_json)
		f.close()
		var detected_errs: Variant = validator.call("validate_chapter", bad_path)
		check("errori_rilevati", detected_errs is Array and (detected_errs as Array).size() >= 2, "validate_chapter deve rilevare speaker non consentiti e salti a etichette inesistenti")

	# Verifica che _run() esista e stampi il resoconto
	if check("metodo_run", has_function(validator, "_run"), "StoryValidator deve implementare il metodo _run()"):
		clear_printed()
		validator.call("_run")
		check("output_run", not printed_text().is_empty(), "_run() deve stampare l'esito della validazione nell'Output")

	var main := await instantiate_main_scene()
	check("main_scene", main != null, "La scena principale deve avviarsi correttamente")
